// The commit message the clean-tree gate proposes (D-181/D-191/D-192). The gate commits the
// user's pending work before the AI may write, so the default text is a SEMANTIC summary of
// what the diff does — generated by the configured model, at most 30 words, in the UI
// language — never a list of paths. The user edits it in the card before committing.
//
// The summarizer is a small side call, outside the conversation and not shown in the
// transcript. The same pieces are reusable by Source Control's own commit box later.

import type { Locale } from "@/i18n";
import type { CallModelInput, CallModelResult } from "./client";
import type { AiSettings, GitSafety } from "./types";

export const MAX_COMMIT_WORDS = 30;

/** A diff longer than this stops being a summary input; the model sees the start, not a novel. */
const DIFF_CHAR_CAP = 12_000;

const LANGUAGE: Record<Locale, string> = { en: "English", it: "Italian" };

const FALLBACK: Record<Locale, string> = {
  en: "chore: save work before AI changes",
  it: "chore: salva il lavoro prima delle modifiche AI",
};

/** The one-paragraph task for the summarizer call: a sentence, not a file list. */
export function buildCommitSystemPrompt(locale: Locale): string {
  return [
    "You write git commit messages for a software project.",
    "Read the diff and reply with ONE sentence, at most " +
      MAX_COMMIT_WORDS +
      " words, in " +
      LANGUAGE[locale] +
      ".",
    'Describe what the change does, the way a person would say it (for example: "Aggiunto il calendario alla pagina todo"); never list or quote file paths.',
    "No markdown, no quotes, no label, no explanation after the sentence.",
  ].join("\n");
}

/** Keep the summarizer input bounded: the start of the diff is the most meaningful part. */
export function capCommitDiff(diff: string): string {
  if (diff.length <= DIFF_CHAR_CAP) return diff;
  return diff.slice(0, DIFF_CHAR_CAP) + "\n[truncated]";
}

/**
 * Normalize what the model wrote into a commit message: no fence, no label, one line, at
 * most 30 words, no trailing punctuation. An empty result means "use the fallback".
 */
export function sanitizeCommitMessage(raw: string): string {
  let text = raw.trim();
  const fenced = /^```(?:[a-zA-Z]+)?\s*([\s\S]*?)\s*```$/.exec(text);
  if (fenced?.[1] !== undefined) text = fenced[1].trim();
  text = text.replace(/^(?:commit message|messaggio(?: di commit)?)\s*:\s*/i, "");
  text = text.replace(/^[\s"'`]+|[\s"'`]+$/g, "");
  text = text.replace(/\s+/g, " ").trim();
  const words = text.split(" ").filter((word) => word.length > 0);
  return words
    .slice(0, MAX_COMMIT_WORDS)
    .join(" ")
    .replace(/[.;,]+$/, "");
}

/** The deterministic last resort when no model/diff is available. */
export function fallbackCommitMessage(locale: Locale): string {
  return FALLBACK[locale];
}

export interface CommitSummaryInput {
  /** The uncommitted diff (staged and unstaged) to describe. */
  diff: string;
  locale: Locale;
  settings: AiSettings;
  call: (input: CallModelInput) => Promise<CallModelResult>;
  signal?: AbortSignal;
}

export interface CommitMessageInput {
  /** The git seam: an absent or failing diff falls back, it never blocks the gate. */
  safety: GitSafety | undefined;
  settings: AiSettings | null;
  locale: Locale;
  call: (input: CallModelInput) => Promise<CallModelResult>;
  signal?: AbortSignal;
}

/** Read the pending diff and summarize it; always resolves to a usable message. */
export async function generateCommitMessage(input: CommitMessageInput): Promise<string> {
  const fallback = fallbackCommitMessage(input.locale);
  const diff = input.safety?.diff;
  if (diff === undefined || input.settings === null) return fallback;
  let text: string;
  try {
    text = await diff.call(input.safety);
  } catch {
    return fallback;
  }
  return summarizeCommitMessage({
    diff: text,
    locale: input.locale,
    settings: input.settings,
    call: input.call,
    ...(input.signal === undefined ? {} : { signal: input.signal }),
  });
}

/** Generate the commit message; never throws and always returns a usable text. */
export async function summarizeCommitMessage(input: CommitSummaryInput): Promise<string> {
  const fallback = fallbackCommitMessage(input.locale);
  const diff = capCommitDiff(input.diff);
  if (diff.trim().length === 0) return fallback;
  try {
    const result = await input.call({
      settings: input.settings,
      system: buildCommitSystemPrompt(input.locale),
      messages: [{ role: "user", content: diff }],
      ...(input.signal === undefined ? {} : { signal: input.signal }),
    });
    if (!result.ok) return fallback;
    return sanitizeCommitMessage(result.text) || fallback;
  } catch {
    // The commit is the user's next step: a failed summarizer must not block the card.
    return fallback;
  }
}
